/bin/bash -lc "python - <<'PY'
from solve import trial
cands=[]
for yaw in [0.0, 1.57079632679]:
  for open_ctrl in [120.0,140.0]:
    for close_ctrl in [90.0,100.0,110.0]:
      for dz in [-0.04,-0.03,-0.02]:
        cands.append({'yaw':yaw,'side_y':0.24,'pre_height':0.80,'open_ctrl':open_ctrl,'grasp_dx':0.01,'grasp_dy':0.0,'grasp_dz':dz,'close_ctrl':close_ctrl,'lift_height':0.82,'return_x':0.38,'return_y':0.18,'final_x':0.34,'final_y':0.24,'final_height':0.70})
for i,p in enumerate(cands,1):
  r=trial(p)
  print(i, 'yaw',round(p['yaw'],2),'open',p['open_ctrl'],'close',p['close_ctrl'],'dz',p['grasp_dz'], 'score',round(r.score,3),'contact',r.ever_contact,'bestx',round(r.best_x,3),'bestz',round(r.best_z,3),'finalz',round(r.final_z,3),'settle',round(r.settle_contact,3))
  if r.score>0.55 or r.best_z>0.48:
    r.sim.save_final_state('/work/final_state.npz')
    print('saved improved candidate')
PY"
